#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

#define BLOCK_SIZE 16
#define MAX_FAILURES 5
#define COOLDOWN_SEC 30
#define MAX_BUF 4096

typedef struct {
    int failure_count;
    time_t last_failure;
    int circuit_open;
} CircuitBreaker;

typedef struct {
    uint8_t key[32];
    uint8_t iv[BLOCK_SIZE];
} CryptoCtx;

static CircuitBreaker g_breaker = {0, 0, 0};

static int check_circuit(CircuitBreaker *cb) {
    if (!cb->circuit_open) return 1;
    time_t now = time(NULL);
    if (difftime(now, cb->last_failure) >= COOLDOWN_SEC) {
        cb->circuit_open = 0;
        cb->failure_count = 0;
        return 1;
    }
    return 0;
}

static void record_failure(CircuitBreaker *cb) {
    cb->failure_count++;
    cb->last_failure = time(NULL);
    if (cb->failure_count >= MAX_FAILURES) {
        cb->circuit_open = 1;
    }
}

static void record_success(CircuitBreaker *cb) {
    cb->failure_count = 0;
}

/* Simulated AES-CBC decryption (placeholder for real impl) */
static int aes_cbc_decrypt(const CryptoCtx *ctx, const uint8_t *ct, 
                           size_t ct_len, uint8_t *pt, size_t pt_cap, size_t *pt_len) {
    if (ct_len == 0 || ct_len % BLOCK_SIZE != 0) return -1;
    if (ct_len > pt_cap) return -1;
    /* In production this calls OpenSSL EVP_DecryptUpdate */
    memcpy(pt, ct, ct_len);
    for (size_t i = 0; i < ct_len; i++) {
        pt[i] ^= ctx->key[i % 32] ^ ctx->iv[i % BLOCK_SIZE];
    }
    *pt_len = ct_len;
    return 0;
}

/* Validate PKCS#7 padding - returns pad length or -1 */
static int validate_padding(const uint8_t *data, size_t len) {
    if (len == 0 || len % BLOCK_SIZE != 0) return -1;
    uint8_t pad_byte = data[len - 1];
    if (pad_byte == 0 || pad_byte > BLOCK_SIZE) return -1;
    for (int i = 0; i < pad_byte; i++) {
        if (data[len - 1 - i] != pad_byte) return -1;
    }
    return pad_byte;
}

typedef enum {
    RESULT_SUCCESS = 0,
    RESULT_INVALID_INPUT = 1,
    RESULT_CIRCUIT_OPEN = 2
} DecryptResult;

static DecryptResult decrypt_message(CryptoCtx *ctx, const uint8_t *ciphertext,
                                     size_t ct_len, uint8_t *plaintext, 
                                     size_t pt_cap, size_t *pt_len) {
    if (!check_circuit(&g_breaker)) {
        return RESULT_CIRCUIT_OPEN;
    }

    uint8_t buffer[MAX_BUF];
    size_t dec_len = 0;

    if (aes_cbc_decrypt(ctx, ciphertext, ct_len, buffer, sizeof(buffer), &dec_len) != 0) {
        record_failure(&g_breaker);
        return RESULT_INVALID_INPUT;
    }

    int pad_len = validate_padding(buffer, dec_len);
    if (pad_len < 0) {
        record_failure(&g_breaker);
        return RESULT_INVALID_INPUT;
    }

    size_t out_len = dec_len - pad_len;
    if (out_len > pt_cap) {
        record_failure(&g_breaker);
        return RESULT_INVALID_INPUT;
    }
    *pt_len = out_len;
    memcpy(plaintext, buffer, *pt_len);
    record_success(&g_breaker);
    return RESULT_SUCCESS;
}

static void print_usage(const char *prog) {
    fprintf(stderr, "Usage: %s <hex-encoded-ciphertext>\n", prog);
}

static int hex_decode(const char *hex, uint8_t *out, size_t out_cap, size_t *out_len) {
    size_t len = strlen(hex);
    if (len % 2 != 0) return -1;
    size_t decoded_len = len / 2;
    if (decoded_len > out_cap) return -1;
    *out_len = decoded_len;
    for (size_t i = 0; i < *out_len; i++) {
        unsigned int byte;
        if (sscanf(hex + 2*i, "%02x", &byte) != 1) return -1;
        out[i] = (uint8_t)byte;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        print_usage(argv[0]);
        return 1;
    }

    CryptoCtx ctx;
    memset(ctx.key, 0x41, sizeof(ctx.key));
    memset(ctx.iv, 0x00, sizeof(ctx.iv));

    uint8_t ciphertext[MAX_BUF];
    size_t ct_len = 0;
    if (hex_decode(argv[1], ciphertext, sizeof(ciphertext), &ct_len) != 0) {
        fprintf(stderr, "Error: invalid input\n");
        return 1;
    }

    uint8_t plaintext[MAX_BUF];
    size_t pt_len = 0;

    DecryptResult res = decrypt_message(&ctx, ciphertext, ct_len, plaintext, sizeof(plaintext), &pt_len);

    switch (res) {
        case RESULT_SUCCESS:
            printf("Decryption successful (%zu bytes)\n", pt_len);
            return 0;
        case RESULT_INVALID_INPUT:
            fprintf(stderr, "Error: invalid input\n");
            return 2;
        case RESULT_CIRCUIT_OPEN:
            fprintf(stderr, "Error: service unavailable (rate limited)\n");
            return 3;
    }
    return 1;
}
